<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { getQuote, saveQuote, type Quote } from "../../api"; const route = useRoute(); const quote = ref<Quote>({ id: "", repairOrderId: String(route.params.id), lines: [{ description: "", quantity: 1, unitPriceCents: 0 }], totalCents: 0, status: "draft" }); const error = ref(""); onMounted(async () => { try { quote.value = await getQuote(String(route.params.id)); } catch { } }); function add() { quote.value.lines.push({ description: "", quantity: 1, unitPriceCents: 0 }); } async function save(status: "draft" | "sent") { try { quote.value = await saveQuote(String(route.params.id), { lines: quote.value.lines, status }); } catch (reason) { error.value = (reason as Error).message; } }</script><template><section class="detail-tab"><h2>Presupuesto</h2><form class="entity-form" @submit.prevent="save('draft')"><label v-for="(line, index) in quote.lines" :key="index">Concepto<input v-model="line.description" required /><input v-model.number="line.quantity" type="number" min="1" /><input v-model.number="line.unitPriceCents" type="number" min="0" /></label><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="add">Anadir linea</button><button type="submit">Guardar borrador</button><button type="button" @click="save('sent')">Enviar presupuesto</button></footer></form></section></template>